-- Canadian fish species.
-- Sources: Canadian Endangered Species Conservation Council. 2022. Wild Species 2020: The General Status of
--   Species in Canada. National General Status Working Group.  |  FishBase v26.06 (Froese & Pauly, eds.), CC BY-NC 4.0.
-- Generated by scripts/build-species-seed.py. Do not edit by hand.

alter table public.species rename column ws_a to lw_a;
alter table public.species rename column ws_b to lw_b;
comment on column public.species.lw_a is 'log10(W g) = lw_a + lw_b * log10(total length mm). From FishBase Bayesian LWR estimates.';
alter table public.species
  add column common_name_fr    text,
  add column order_name        text,
  add column fishbase_id       integer,
  add column lw_method         text,
  add column max_length_mm     integer,
  add column freshwater        boolean,
  add column brackish          boolean,
  add column saltwater         boolean,
  add column game_fish         boolean not null default false,
  add column in_canada         boolean not null default false,
  add column native_to_canada  boolean,
  add column regions           text[] not null default '{}',
  add column wild_species_code text unique,
  add column national_rank     text;
comment on column public.species.regions is 'Wild Species 2020 regions: provinces/territories (NF = Newfoundland, LB = Labrador) and oceans PAC, WAO, EAO, ATL.';
create index species_regions_idx on public.species using gin (regions);

on conflict (id) do update set common_name = excluded.common_name, common_name_fr = excluded.common_name_fr, scientific_name = excluded.scientific_name, family = excluded.family, order_name = excluded.order_name, fishbase_id = excluded.fishbase_id, lw_a = excluded.lw_a, lw_b = excluded.lw_b, lw_method = excluded.lw_method, max_length_mm = excluded.max_length_mm, freshwater = excluded.freshwater, brackish = excluded.brackish, saltwater = excluded.saltwater, game_fish = excluded.game_fish, in_canada = excluded.in_canada, native_to_canada = excluded.native_to_canada, regions = excluded.regions, wild_species_code = excluded.wild_species_code, national_rank = excluded.national_rank;

-- 'gar' was a family-level placeholder in the first seed; real gar species are listed now.
delete from public.species where id = 'gar' and not exists (select 1 from public.catches where species_id = 'gar');
